/// <summary>
/// Return TAMRebateTable record from TAMRebateTrans
/// </summary>
/// <param name = "_forUpdate">Select for update</param>
/// <returns><c>TAMRebateTable</c> record</returns>
public TAMRebateTable METTAMRebateTable(boolean _forUpdate = false)
{
    return TAMRebateTable::find(this.RebateId, _forUpdate);
}

/// <summary>
/// Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
/// After TAMRebateTrans are inserted, TAMRebateTransBasisTotal\distributeDateTransRebateAmount updates the rebateTrans.RebateAmount line 114
/// This setPostingAmount() is called just after that and before the update
/// </summary>
/// <param name = "_useClaimProcess">Use claim process</param>
public void setPostingAmount(boolean _useClaimProcess)
{
    if (this.metRebateDeal().METVolumetricTierDeal)
    {
        METTierRateTrans tierRateTrans = METTierRateTrans::find(this.RebateId, this.RebateRefDate, TAMRebateDateTrans::find(this.RebateTransId).RebateTransactionType);

        if (tierRateTrans)
        {
            // Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
            // Apply rounding when source transaction is created as per standard
            //_rebateTrans.RebateAmount = (_rebateTrans.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
            this.RebateAmount = CurrencyExchangeHelper::amount((this.RebateRefAmount * tierRateTrans.EligibleRebate)/100, this.CurrencyCode);
        }
    }  

    next setPostingAmount(_useClaimProcess);
}

/// <summary>
/// Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
/// Method to retrieve the rebate deal from the transaction
/// </summary>
/// <param name = "_forupdate">Select for update</param>
/// <returns><c>TAMRebateDeal</c></returns>
public TAMRebateDeal metRebateDeal(boolean _forupdate = false)
{
    return TAMRebateDeal::find(TAMRebateDateTrans::find(this.RebateTransId).RebateDeal, _forupdate);
}
